package com.ashkan.hotel;

import java.io.IOException;
import java.math.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.time.*;
import java.util.*;

/** Parking inventory, vehicle visits and hotel transfer reservations. */
public final class ParkingService {
    public enum SlotStatus { AVAILABLE, OCCUPIED, OUT_OF_SERVICE }
    public enum VisitStatus { ACTIVE, CLOSED, CANCELLED }
    public enum TransferStatus { BOOKED, CONFIRMED, COMPLETED, CANCELLED }
    public record Slot(String code,String zone,String description,boolean enabled) {
        public Slot { code=req(code);zone=req(zone);description=clean(description); }
    }
    public record Visit(long id,String slotCode,String guest,String plate,String vehicleType,LocalDateTime entry,LocalDateTime exit,BigDecimal fee,VisitStatus status) {
        public Visit { slotCode=req(slotCode);guest=req(guest);plate=req(plate).toUpperCase(Locale.ROOT);vehicleType=clean(vehicleType);Objects.requireNonNull(entry);fee=money(fee);Objects.requireNonNull(status);if(exit!=null&&exit.isBefore(entry))throw new IllegalArgumentException("Exit cannot be before entry"); }
    }
    public record Driver(String code,String name,String phone,String vehicle,String plate,boolean active) {
        public Driver { code=req(code);name=req(name);phone=clean(phone);vehicle=req(vehicle);plate=req(plate).toUpperCase(Locale.ROOT); }
    }
    public record Transfer(long id,String guest,String pickup,String destination,String driverCode,LocalDateTime pickupAt,int passengers,BigDecimal fare,TransferStatus status,String notes) {
        public Transfer { guest=req(guest);pickup=req(pickup);destination=req(destination);driverCode=clean(driverCode);Objects.requireNonNull(pickupAt);if(passengers<1)throw new IllegalArgumentException("Passengers must be positive");fare=money(fare);Objects.requireNonNull(status);notes=clean(notes); }
    }
    private final Path file; private final Clock clock; private final Map<String,Slot> slots=new TreeMap<>(String.CASE_INSENSITIVE_ORDER); private final Map<String,Driver> drivers=new TreeMap<>(String.CASE_INSENSITIVE_ORDER); private final List<Visit> visits=new ArrayList<>(); private final List<Transfer> transfers=new ArrayList<>(); private long nextVisit=1,nextTransfer=1;
    public ParkingService(){this(Path.of(System.getProperty("user.home"),".ashkan-hotelsphere","parking.tsv"),Clock.systemDefaultZone());}
    public ParkingService(Path file,Clock clock){this.file=Objects.requireNonNull(file);this.clock=Objects.requireNonNull(clock);try{Files.createDirectories(file.toAbsolutePath().getParent());if(Files.exists(file))load();}catch(IOException e){throw new IllegalStateException("Cannot load parking data",e);}}
    private static String clean(String s){return s==null?"":s.strip();} private static String req(String s){String x=clean(s);if(x.isBlank())throw new IllegalArgumentException("Required value is missing");return x;}
    private static BigDecimal money(BigDecimal x){Objects.requireNonNull(x);if(x.signum()<0)throw new IllegalArgumentException("Amount cannot be negative");return x.setScale(2,RoundingMode.HALF_UP);}
    private static boolean overlap(LocalDateTime a,LocalDateTime b,LocalDateTime c,LocalDateTime d){return a.isBefore(d)&&c.isBefore(b);}
    public synchronized void saveSlot(Slot x)throws IOException{Slot old=slots.put(x.code(),x);try{persist();}catch(IOException e){if(old==null)slots.remove(x.code());else slots.put(old.code(),old);throw e;}}
    public synchronized void saveDriver(Driver x)throws IOException{Driver old=drivers.put(x.code(),x);try{persist();}catch(IOException e){if(old==null)drivers.remove(x.code());else drivers.put(old.code(),old);throw e;}}
    public synchronized List<Slot> slots(){return List.copyOf(slots.values());} public synchronized List<Driver> drivers(){return List.copyOf(drivers.values());}
    public synchronized List<Visit> visits(){return visits.stream().sorted(Comparator.comparing(Visit::entry).reversed()).toList();} public synchronized List<Transfer> transfers(){return transfers.stream().sorted(Comparator.comparing(Transfer::pickupAt).reversed()).toList();}
    public synchronized SlotStatus slotStatus(String code){Slot s=slots.get(code);if(s==null||!s.enabled())return SlotStatus.OUT_OF_SERVICE;return visits.stream().anyMatch(v->v.slotCode().equalsIgnoreCase(code)&&v.status()==VisitStatus.ACTIVE)?SlotStatus.OCCUPIED:SlotStatus.AVAILABLE;}
    public synchronized Visit checkIn(String slotCode,String guest,String plate,String vehicleType,BigDecimal fee)throws IOException{Slot s=slots.get(req(slotCode));if(s==null||!s.enabled())throw new IllegalArgumentException("Parking slot unavailable");if(slotStatus(slotCode)!=SlotStatus.AVAILABLE)throw new IllegalStateException("Parking slot is occupied");String p=req(plate);if(visits.stream().anyMatch(v->v.plate().equalsIgnoreCase(p)&&v.status()==VisitStatus.ACTIVE))throw new IllegalStateException("Vehicle already has an active visit");Visit v=new Visit(nextVisit++,slotCode,guest,p,vehicleType,LocalDateTime.now(clock),null,fee,VisitStatus.ACTIVE);visits.add(v);try{persist();}catch(IOException e){visits.remove(v);nextVisit--;throw e;}return v;}
    public synchronized Visit checkOut(long id)throws IOException{int i=visitIndex(id);Visit old=visits.get(i);if(old.status()!=VisitStatus.ACTIVE)throw new IllegalStateException("Visit is not active");Visit v=new Visit(old.id(),old.slotCode(),old.guest(),old.plate(),old.vehicleType(),old.entry(),LocalDateTime.now(clock),old.fee(),VisitStatus.CLOSED);visits.set(i,v);try{persist();}catch(IOException e){visits.set(i,old);throw e;}return v;}
    private int visitIndex(long id){for(int i=0;i<visits.size();i++)if(visits.get(i).id()==id)return i;throw new IllegalArgumentException("Unknown parking visit");}
    public synchronized Transfer bookTransfer(String guest,String pickup,String destination,String driverCode,LocalDateTime at,int passengers,BigDecimal fare,String notes)throws IOException{Driver d=drivers.get(clean(driverCode));if(!clean(driverCode).isBlank()&&(d==null||!d.active()))throw new IllegalArgumentException("Driver is unavailable");if(at.isBefore(LocalDateTime.now(clock)))throw new IllegalArgumentException("Pickup cannot be in the past");if(d!=null)for(Transfer t:transfers)if(t.driverCode().equalsIgnoreCase(driverCode)&&t.status()!=TransferStatus.CANCELLED&&t.status()!=TransferStatus.COMPLETED&&overlap(at.minusHours(1),at.plusHours(1),t.pickupAt().minusHours(1),t.pickupAt().plusHours(1)))throw new IllegalStateException("Driver has a conflicting transfer");Transfer t=new Transfer(nextTransfer++,guest,pickup,destination,driverCode,at,passengers,fare,TransferStatus.BOOKED,notes);transfers.add(t);try{persist();}catch(IOException e){transfers.remove(t);nextTransfer--;throw e;}return t;}
    public synchronized void updateTransfer(long id,TransferStatus status)throws IOException{for(int i=0;i<transfers.size();i++){Transfer o=transfers.get(i);if(o.id()==id){if(o.status()==TransferStatus.CANCELLED||o.status()==TransferStatus.COMPLETED)throw new IllegalStateException("Transfer is closed");Transfer n=new Transfer(o.id(),o.guest(),o.pickup(),o.destination(),o.driverCode(),o.pickupAt(),o.passengers(),o.fare(),status,o.notes());transfers.set(i,n);try{persist();}catch(IOException e){transfers.set(i,o);throw e;}return;}}throw new IllegalArgumentException("Unknown transfer");}
    public synchronized BigDecimal parkingRevenue(){return visits.stream().filter(v->v.status()==VisitStatus.CLOSED).map(Visit::fee).reduce(BigDecimal.ZERO,BigDecimal::add);}
    public synchronized BigDecimal transferRevenue(){return transfers.stream().filter(t->t.status()==TransferStatus.COMPLETED).map(Transfer::fare).reduce(BigDecimal.ZERO,BigDecimal::add);}
    public synchronized String csv(){StringBuilder b=new StringBuilder("Type,ID,Guest,Vehicle or route,Slot or driver,Start,End,Amount,Status\n");for(Visit v:visits())b.append("PARKING,").append(v.id()).append(',').append(q(v.guest())).append(',').append(q(v.plate())).append(',').append(q(v.slotCode())).append(',').append(v.entry()).append(',').append(v.exit()==null?"":v.exit()).append(',').append(v.fee()).append(',').append(v.status()).append('\n');for(Transfer t:transfers())b.append("TRANSFER,").append(t.id()).append(',').append(q(t.guest())).append(',').append(q(t.pickup()+" -> "+t.destination())).append(',').append(q(t.driverCode())).append(',').append(t.pickupAt()).append(",,").append(t.fare()).append(',').append(t.status()).append('\n');return b.toString();}
    private static String q(String s){return "\""+clean(s).replace("\"","\"\"")+"\"";} private static String enc(String s){return Base64.getEncoder().encodeToString(clean(s).getBytes(StandardCharsets.UTF_8));} private static String dec(String s){return new String(Base64.getDecoder().decode(s),StandardCharsets.UTF_8);}
    private void persist()throws IOException{Path tmp=Files.createTempFile(file.toAbsolutePath().getParent(),"parking-",".tmp");try{List<String> rows=new ArrayList<>();for(Slot s:slots.values())rows.add(String.join("\t","S",enc(s.code()),enc(s.zone()),enc(s.description()),Boolean.toString(s.enabled())));for(Driver d:drivers.values())rows.add(String.join("\t","D",enc(d.code()),enc(d.name()),enc(d.phone()),enc(d.vehicle()),enc(d.plate()),Boolean.toString(d.active())));for(Visit v:visits)rows.add(String.join("\t","V",Long.toString(v.id()),enc(v.slotCode()),enc(v.guest()),enc(v.plate()),enc(v.vehicleType()),v.entry().toString(),v.exit()==null?"":v.exit().toString(),v.fee().toPlainString(),v.status().name()));for(Transfer t:transfers)rows.add(String.join("\t","T",Long.toString(t.id()),enc(t.guest()),enc(t.pickup()),enc(t.destination()),enc(t.driverCode()),t.pickupAt().toString(),Integer.toString(t.passengers()),t.fare().toPlainString(),t.status().name(),enc(t.notes())));Files.write(tmp,rows,StandardCharsets.UTF_8);try{Files.move(tmp,file,StandardCopyOption.ATOMIC_MOVE,StandardCopyOption.REPLACE_EXISTING);}catch(AtomicMoveNotSupportedException e){Files.move(tmp,file,StandardCopyOption.REPLACE_EXISTING);}}finally{Files.deleteIfExists(tmp);}}
    private void load()throws IOException{for(String row:Files.readAllLines(file,StandardCharsets.UTF_8)){String[] f=row.split("\t",-1);try{switch(f[0]){case "S"->{if(f.length==5){Slot s=new Slot(dec(f[1]),dec(f[2]),dec(f[3]),Boolean.parseBoolean(f[4]));slots.put(s.code(),s);}}case "D"->{if(f.length==7){Driver d=new Driver(dec(f[1]),dec(f[2]),dec(f[3]),dec(f[4]),dec(f[5]),Boolean.parseBoolean(f[6]));drivers.put(d.code(),d);}}case "V"->{if(f.length==10){Visit v=new Visit(Long.parseLong(f[1]),dec(f[2]),dec(f[3]),dec(f[4]),dec(f[5]),LocalDateTime.parse(f[6]),f[7].isBlank()?null:LocalDateTime.parse(f[7]),new BigDecimal(f[8]),VisitStatus.valueOf(f[9]));visits.add(v);nextVisit=Math.max(nextVisit,v.id()+1);}}case "T"->{if(f.length==11){Transfer t=new Transfer(Long.parseLong(f[1]),dec(f[2]),dec(f[3]),dec(f[4]),dec(f[5]),LocalDateTime.parse(f[6]),Integer.parseInt(f[7]),new BigDecimal(f[8]),TransferStatus.valueOf(f[9]),dec(f[10]));transfers.add(t);nextTransfer=Math.max(nextTransfer,t.id()+1);}}}}catch(RuntimeException ignored){}}}
}
